arduino.setup:
display_${COMP_SUFFIX}.begin();
display_${COMP_SUFFIX}.setContrast(50);
display_${COMP_SUFFIX}.clearDisplay();
display_${COMP_SUFFIX}.setTextSize(1);
display_${COMP_SUFFIX}.setTextColor(BLACK);
display_${COMP_SUFFIX}.setCursor(0,0);
display_${COMP_SUFFIX}.println("OpenHW Studio");
display_${COMP_SUFFIX}.println("Nokia 5110");
display_${COMP_SUFFIX}.display();
delay(2000);

arduino.loop:
display_${COMP_SUFFIX}.clearDisplay();
display_${COMP_SUFFIX}.setCursor(0,0);
display_${COMP_SUFFIX}.print("Timer: ");
display_${COMP_SUFFIX}.print(millis()/1000);
display_${COMP_SUFFIX}.println("s");
display_${COMP_SUFFIX}.display();
delay(500);
